// ============================================
// DATA VALIDATION - Edge Processing Step 1
// ============================================
// Validates incoming sensor data for completeness
// and value range correctness.
// Output 1: Valid data
// Output 2: Invalid data (rejected)
// ============================================

var data = msg.payload;
var errors = [];

// Check required fields exist
if (!data.tankId || typeof data.tankId !== 'string') {
    errors.push('Missing or invalid tankId');
}
if (data.pH === undefined || data.pH === null || typeof data.pH !== 'number') {
    errors.push('Missing or invalid pH');
}
if (data.turbidity === undefined || data.turbidity === null || typeof data.turbidity !== 'number') {
    errors.push('Missing or invalid turbidity');
}
if (data.temperature === undefined || data.temperature === null || typeof data.temperature !== 'number') {
    errors.push('Missing or invalid temperature');
}
if (data.waterLevel === undefined || data.waterLevel === null || typeof data.waterLevel !== 'number') {
    errors.push('Missing or invalid waterLevel');
}
if (!data.timestamp) {
    errors.push('Missing timestamp');
}

// Validate value ranges
if (typeof data.pH === 'number' && (data.pH < 0 || data.pH > 14)) {
    errors.push('pH out of range (0-14): ' + data.pH);
}
if (typeof data.turbidity === 'number' && data.turbidity < 0) {
    errors.push('Turbidity cannot be negative: ' + data.turbidity);
}
if (typeof data.temperature === 'number' && (data.temperature < -50 || data.temperature > 100)) {
    errors.push('Temperature out of sensor range (-50 to 100): ' + data.temperature);
}
if (typeof data.waterLevel === 'number' && (data.waterLevel < 0 || data.waterLevel > 100)) {
    errors.push('Water level out of range (0-100): ' + data.waterLevel);
}

if (errors.length > 0) {
    // Invalid data - send to output 2
    msg.payload = {
        error: 'Validation failed',
        reasons: errors,
        originalData: data
    };
    node.warn('Data validation failed for ' + (data.tankId || 'unknown') + ': ' + errors.join(', '));
    return [null, msg];
}

// Valid data - send to output 1
return [msg, null];

// ============================================
// THRESHOLD ANALYSIS & STATUS CLASSIFICATION
// Edge Processing Step 2
// ============================================
// Applies configurable thresholds to sensor data
// and classifies overall tank status as:
// SAFE / WARNING / UNSAFE
// ============================================

var data = msg.payload;
var alerts = [];
var paramStatuses = [];

// ============================================
// CONFIGURABLE THRESHOLDS
// Modify these values to adjust sensitivity
// ============================================
var THRESHOLDS = {
    pH: {
        SAFE_MIN: 6.5,
        SAFE_MAX: 8.5,
        WARN_MIN: 5.5,
        WARN_MAX: 9.5
    },
    turbidity: {
        SAFE_MAX: 5,
        WARN_MAX: 10
    },
    temperature: {
        SAFE_MIN: 20,
        SAFE_MAX: 35,
        WARN_MAX: 40
    },
    waterLevel: {
        SAFE_MIN: 30,
        WARN_MIN: 10
    }
};

// --- pH Analysis ---
if (data.pH >= THRESHOLDS.pH.SAFE_MIN && data.pH <= THRESHOLDS.pH.SAFE_MAX) {
    paramStatuses.push('SAFE');
} else if (data.pH >= THRESHOLDS.pH.WARN_MIN && data.pH <= THRESHOLDS.pH.WARN_MAX) {
    paramStatuses.push('WARNING');
    if (data.pH < THRESHOLDS.pH.SAFE_MIN) {
        alerts.push('Low pH detected: ' + data.pH);
    } else {
        alerts.push('High pH detected: ' + data.pH);
    }
} else {
    paramStatuses.push('UNSAFE');
    if (data.pH < THRESHOLDS.pH.WARN_MIN) {
        alerts.push('CRITICAL: Very low pH: ' + data.pH);
    } else {
        alerts.push('CRITICAL: Very high pH: ' + data.pH);
    }
}

// --- Turbidity Analysis ---
if (data.turbidity <= THRESHOLDS.turbidity.SAFE_MAX) {
    paramStatuses.push('SAFE');
} else if (data.turbidity <= THRESHOLDS.turbidity.WARN_MAX) {
    paramStatuses.push('WARNING');
    alerts.push('High turbidity detected: ' + data.turbidity + ' NTU');
} else {
    paramStatuses.push('UNSAFE');
    alerts.push('CRITICAL: Very high turbidity: ' + data.turbidity + ' NTU');
}

// --- Temperature Analysis ---
if (data.temperature >= THRESHOLDS.temperature.SAFE_MIN && data.temperature <= THRESHOLDS.temperature.SAFE_MAX) {
    paramStatuses.push('SAFE');
} else if (data.temperature <= THRESHOLDS.temperature.WARN_MAX) {
    paramStatuses.push('WARNING');
    if (data.temperature < THRESHOLDS.temperature.SAFE_MIN) {
        alerts.push('Low temperature detected: ' + data.temperature + '°C');
    } else {
        alerts.push('High temperature detected: ' + data.temperature + '°C');
    }
} else {
    paramStatuses.push('UNSAFE');
    alerts.push('CRITICAL: Very high temperature: ' + data.temperature + '°C');
}

// --- Water Level Analysis ---
if (data.waterLevel >= THRESHOLDS.waterLevel.SAFE_MIN) {
    paramStatuses.push('SAFE');
} else if (data.waterLevel >= THRESHOLDS.waterLevel.WARN_MIN) {
    paramStatuses.push('WARNING');
    alerts.push('Low water level: ' + data.waterLevel + '%');
} else {
    paramStatuses.push('UNSAFE');
    alerts.push('CRITICAL: Very low water level: ' + data.waterLevel + '%');
}

// --- Overall Status Classification ---
var overallStatus;
if (paramStatuses.includes('UNSAFE')) {
    overallStatus = 'UNSAFE';
} else if (paramStatuses.includes('WARNING')) {
    overallStatus = 'WARNING';
} else {
    overallStatus = 'SAFE';
}

// Build processed message
msg.payload = {
    tankId: data.tankId,
    pH: data.pH,
    turbidity: data.turbidity,
    temperature: data.temperature,
    waterLevel: data.waterLevel,
    status: overallStatus,
    alerts: alerts,
    timestamp: data.timestamp
};

// Store status in flow context for monitoring
flow.set('lastStatus_' + data.tankId, {
    status: overallStatus,
    alerts: alerts,
    timestamp: data.timestamp
});

node.status({
    fill: overallStatus === 'SAFE' ? 'green' : (overallStatus === 'WARNING' ? 'yellow' : 'red'),
    shape: 'dot',
    text: data.tankId + ': ' + overallStatus
});

return msg;

// ============================================
// PREPARE INFLUXDB WRITE
// Converts processed data to InfluxDB line protocol
// and sets up HTTP request headers
// ============================================

var data = msg.payload;

// Get InfluxDB config from environment variables
var influxUrl = env.get('INFLUXDB_URL') || 'http://influxdb:8086';
var org = env.get('INFLUXDB_ORG') || 'WaterMonitoring';
var bucket = env.get('INFLUXDB_BUCKET') || 'water_quality';
var token = env.get('INFLUXDB_TOKEN') || 'my-super-secret-token-12345';

// Build InfluxDB line protocol
// Format: measurement,tag=value field=value timestamp
var lineProtocol = 'water_quality,tankId=' + data.tankId + ' ' +
    'pH=' + data.pH + ',' +
    'turbidity=' + data.turbidity + ',' +
    'temperature=' + data.temperature + ',' +
    'waterLevel=' + data.waterLevel + ',' +
    'status="' + data.status + '",' +
    'alerts="' + (data.alerts.join('; ') || 'none') + '"';

// Set up HTTP request
delete msg.url;
delete msg.method;
msg.headers = {
    'Authorization': 'Token ' + token,
    'Content-Type': 'text/plain; charset=utf-8'
};
msg.payload = lineProtocol;

return msg;

// ============================================
// PREPARE ECLIPSE DITTO DIGITAL TWIN UPDATE
// Formats processed data for Ditto REST API
// PUT /api/2/things/water:{tankId}/features/waterQuality/properties
// ============================================

var data = msg.payload;

// Get Ditto URL from environment variables
var dittoUrl = env.get('DITTO_URL') || 'http://nginx/api/2';

// Set up HTTP request to update digital twin
msg.url = dittoUrl + '/things/water:' + data.tankId + '/features/waterQuality/properties';
msg.method = 'PUT';
msg.headers = {
    'Content-Type': 'application/json'
};

msg.payload = {
    pH: data.pH,
    turbidity: data.turbidity,
    temperature: data.temperature,
    waterLevel: data.waterLevel,
    status: data.status,
    alerts: data.alerts,
    timestamp: data.timestamp
};

return msg;

// ============================================
// ALERT CHECK
// Generates alert messages for WARNING/UNSAFE
// conditions and publishes to water/alerts topic
// ============================================

var data = msg.payload;

// Only generate alerts for non-SAFE conditions
if (data.status === 'SAFE') {
    return [null, msg];
}

// Build alert message
var alertMsg = {
    payload: JSON.stringify({
        tankId: data.tankId,
        status: data.status,
        message: data.alerts.join(', '),
        alerts: data.alerts,
        pH: data.pH,
        turbidity: data.turbidity,
        temperature: data.temperature,
        waterLevel: data.waterLevel,
        timestamp: data.timestamp
    })
};

node.status({
    fill: data.status === 'WARNING' ? 'yellow' : 'red',
    shape: 'ring',
    text: data.tankId + ': ' + data.status + ' - ' + data.alerts[0]
});

return [alertMsg, null];
